        assert r.score == bs, (ref, qry, params, r.score, bs)
        assert r.cigar == bc, (ref, qry, params, r.cigar, bc)
        assert (r.reference_start, r.reference_end) == (0, len(ref))
        assert (r.query_start, r.query_end) == (0, len(qry))
