"""Brute-force cross-check of the DP against exhaustive alignments."""
import itertools
import random
import sys

sys.path.insert(0, ".")
from genome_variant.alignment import align_pair
from genome_variant.sequence_io import SequenceRecord


def merge(ops):
    out = []
    for op in ops:
        if out and out[-1][1] == op:
            out[-1][0] += 1
        else:
            out.append([1, op])
    return "".join(f"{c}{o}" for c, o in out)


def score_ops(ops, ref, qry, M, X, O, E):
    sc = 0
    last = None
    for op in ops:
        if op in "=X":
            sc += M if op == "=" else -X
        else:
            sc -= O if last != op else E
        last = op
    return sc


def enumerate_paths(m, n):
    """All sequences of =/X, D, I steps from (0,0) to (m,n)."""
    paths = []

    def rec(i, j, ops):
        if i == m and j == n:
            paths.append(tuple(ops))
            return
        if i < m and j < n:
            rec(i + 1, j + 1, ops + ["S"])
        if i < m:
            rec(i + 1, j, ops + ["D"])
        if j < n:
            rec(i, j + 1, ops + ["I"])

    rec(0, 0, [])
    return paths


def brute_global(ref, qry, M, X, O, E):
    best = None
    for path in enumerate_paths(len(ref), len(qry)):
        ops = []
        ii = jj = 0
        for step in path:
            if step == "S":
                ops.append("=" if ref[ii] == qry[jj] else "X")
                ii += 1
                jj += 1
            elif step == "D":
                ops.append("D")
                ii += 1
            else:
                ops.append("I")
                jj += 1
        sc = score_ops(ops, ref, qry, M, X, O, E)
        c = merge(ops)
        key = (sc, 0, len(ref), 0, len(qry), c)
        if best is None or (-sc, c) < (-best[0], best[1]):
            best = (sc, c)
    return best


def brute_local(ref, qry, M, X, O, E):
    best = None
    for a in range(len(ref)):
        for b in range(a + 1, len(ref) + 1):
            for c in range(len(qry)):
                for d in range(c + 1, len(qry) + 1):
                    rseg, qseg = ref[a:b], qry[c:d]
                    for path in enumerate_paths(len(rseg), len(qseg)):
                        if path[0] != "S":
                            continue
                        ops = []
                        ii = jj = 0
                        for step in path:
                            if step == "S":
                                ops.append("=" if rseg[ii] == qseg[jj] else "X")
                                ii += 1
                                jj += 1
                            elif step == "D":
                                ops.append("D")
                                ii += 1
                            else:
                                ops.append("I")
                                jj += 1
                        sc = score_ops(ops, rseg, qseg, M, X, O, E)
                        if sc <= 0:
                            continue
                        cg = merge(ops)
                        key = (-sc, a, b, c, d, cg)
                        if best is None or key < best:
                            best = key
    if best is None:
        return None
    return (-best[0], best[1], best[2], best[3], best[4], best[5])


def check_case(ref, qry, mode, params):
    M, X, O, E = params
    r = align_pair(SequenceRecord("r", ref), SequenceRecord("q", qry), mode, M, X, O, E)
    if mode == "global":
        bs, bc = brute_global(ref, qry, M, X, O, E)
        assert r.score == bs, (ref, qry, params, r.score, bs)
        assert r.cigar == bc, (ref, qry, params, r.cigar, bc)
        assert (r.reference_start, r.reference_end) == (0, len(ref))
        assert (r.query_start, r.query_end) == (0, len(qry))
    else:
        b = brute_local(ref, qry, M, X, O, E)
        if b is None:
            assert r.score == 0 and r.cigar == ""
            assert (r.reference_start, r.reference_end, r.query_start, r.query_end) == (0, 0, 0, 0)
        else:
            bs, a, bb, c, d, bc = b
            assert r.score == bs, (ref, qry, params, r.score, bs)
            assert (r.reference_start, r.reference_end, r.query_start, r.query_end) == (a, bb, c, d), (
                ref, qry, params,
                (r.reference_start, r.reference_end, r.query_start, r.query_end),
                (a, bb, c, d),
            )
            assert r.cigar == bc, (ref, qry, params, r.cigar, bc)
    # verify aligned strings reconstruct from the cigar and coordinates
    ii, jj = r.reference_start, r.query_start
    exp_r, exp_q = [], []
    digits = ""
    for ch in r.cigar:
        if ch.isdigit():
            digits += ch
            continue
        count = int(digits)
        digits = ""
        for _ in range(count):
            if ch in ("=", "X"):
                exp_r.append(ref[ii]); exp_q.append(qry[jj]); ii += 1; jj += 1
            elif ch == "D":
                exp_r.append(ref[ii]); exp_q.append("-"); ii += 1
            else:
                exp_r.append("-"); exp_q.append(qry[jj]); jj += 1
    assert "".join(exp_r) == r.aligned_reference, r
    assert "".join(exp_q) == r.aligned_query, r
    assert ii == r.reference_end and jj == r.query_end, r
    if r.cigar:
        ops = []
        digits = ""
        for ch in r.cigar:
            if ch.isdigit():
                digits += ch
            else:
                ops.extend([ch] * int(digits)); digits = ""
        assert score_ops(ops, ref[r.reference_start:r.reference_end],
                         qry[r.query_start:r.query_end], M, X, O, E) == r.score, r
        assert r.aligned_reference.replace("-", "") == ref[r.reference_start:r.reference_end]
        assert r.aligned_query.replace("-", "") == qry[r.query_start:r.query_end]
    return r


def random_cases():
    random.seed(1234)
    param_sets = [(1, 0, 0, 0), (2, 1, 2, 1), (1, 5, 3, 1), (3, 2, 0, 0), (2, 3, 5, 2), (1, 1, 10, 1)]
    bases = "ACGT"
    count = 0
    for trial in range(400):
        m = random.randint(0, 5)
        n = random.randint(0, 5)
        ref = "".join(random.choice(bases) for _ in range(m))
        qry = "".join(random.choice(bases) for _ in range(n))
        params = random.choice(param_sets)
        for mode in ("global", "local"):
            if mode == "global":
                check_case(ref, qry, mode, params)
            else:
                check_case(ref, qry, mode, params)
            count += 1
    print(f"OK {count} random cases")


def edge_cases():
    check_case("", "", "global", (2, 3, 5, 2))
    check_case("A", "", "global", (2, 3, 5, 2))
    check_case("", "A", "global", (2, 0, 0, 0))
    check_case("AAA", "AAA", "local", (1, 0, 0, 0))
    check_case("ACGT", "ACGT", "global", (2, 1, 3, 1))
    check_case("AAAA", "AA", "local", (1, 1, 1, 1))
    check_case("G", "A", "local", (1, 0, 0, 0))
