def _read_single_record(
    path: str,
    fmt: str,
    parser: argparse.ArgumentParser,
    label: str,
) -> tuple[SequenceRecord | None, object, bool, int]:
    """Read exactly one record from *path*.

    Returns ``(record, stream, close, exit_code)``; *record* is ``None``
    when the invocation failed and *exit_code* is then ``1`` or ``2``.
    ``"-"`` reads from standard input.
    """
    if path == "-":
        stream = sys.stdin
        close = False
    else:
        try:
            stream = open(path, "r", encoding="utf-8", newline="")
        except OSError as exc:
            print(f"{parser.prog}: {label}: {exc}", file=sys.stderr)
            return None, None, False, 1
        close = True

    try:
        records = read_sequences(stream, format=fmt)
        try:
            first = next(records)
        except StopIteration:
            raise SequenceFormatError(f"{label}: empty input")
        try:
            next(records)
        except StopIteration:
            return first, stream, close, 0
        raise SequenceFormatError(f"{label}: expected exactly one record, got more")
    except (SequenceFormatError, SequenceValidationError, ValueError) as exc:
        if close:
            stream.close()
        print(f"{parser.prog}: {exc}", file=sys.stderr)
        return None, None, False, 2
    except OSError as exc:
        if close:
            stream.close()
        print(f"{parser.prog}: {label}: {exc}", file=sys.stderr)
        return None, None, False, 1


def _alignment_to_json(result: PairwiseAlignment) -> str:
    return json.dumps(
        {
            "reference": result.reference,
            "query": result.query,
            "mode": result.mode,
            "score": result.score,
            "reference_start": result.reference_start,
            "reference_end": result.reference_end,
            "query_start": result.query_start,
            "query_end": result.query_end,
            "cigar": result.cigar,
            "aligned_reference": result.aligned_reference,
            "aligned_query": result.aligned_query,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    )


def _run_align_pair(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.reference == "-" and args.query == "-":
        print(
            f"{parser.prog}: reference and query cannot both be read from standard input",
            file=sys.stderr,
        )
        return 2

    reference_record, ref_stream, close_ref, ref_code = _read_single_record(
        args.reference, args.reference_format, parser, "reference"
    )
    if reference_record is None:
        return ref_code

    query_record, query_stream, close_query, query_code = _read_single_record(
        args.query, args.query_format, parser, "query"
    )
    if query_record is None:
        if close_ref:
            ref_stream.close()
        return query_code

    try:
        try:
            result = align_pair(
                reference_record,
                query_record,
                mode=args.mode,
                match_score=args.match,
                mismatch_penalty=args.mismatch,
                gap_open=args.gap_open,
                gap_extend=args.gap_extend,
            )
        except (SequenceValidationError, ValueError) as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 2
        text = _alignment_to_json(result) + "\n"

        if args.output == "-":
            # Keep output byte-stable across platforms: no newline
            # translation on standard output.
            if hasattr(sys.stdout, "reconfigure"):
                sys.stdout.reconfigure(newline="")
            try:
                sys.stdout.write(text)
                sys.stdout.flush()

    ]
    delete_grid = [[None] * (n + 1) for _ in range(m + 1)]
    insert_grid = [[None] * (n + 1) for _ in range(m + 1)]

    best: tuple[int, int, int, int, int] | None = None  # score + coords

    def earlier_start(
        winner: tuple[int, int, int] | None, candidate: tuple[int, int, int] | None
    ) -> tuple[int, int, int] | None:
        if candidate is None:
            return winner
        if winner is None or candidate[0] > winner[0] or (
            candidate[0] == winner[0] and candidate[1:] < winner[1:]
        ):
            return candidate
        return winner

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            substitution = match if ref[i - 1] == qry[j - 1] else -mismatch

            diagonal: tuple[int, int, int] | None = None
            for grid in (match_grid, delete_grid, insert_grid):
                pred = grid[i - 1][j - 1]
                if pred is not None:
                    diagonal = earlier_start(
                        diagonal,
                        (pred[0] + substitution, pred[1], pred[2]),
                    )
            restart: tuple[int, int, int] = (
                substitution,
                i - 1,
                j - 1,
            )
            match_grid[i][j] = earlier_start(diagonal, restart)

            deletion: tuple[int, int, int] | None = None
            for grid, cost in (
                (match_grid, gap_open),
                (insert_grid, gap_open),
            ):
                pred = grid[i - 1][j]
                if pred is not None:
                    deletion = earlier_start(
                        deletion, (pred[0] - cost, pred[1], pred[2])
                    )
            pred = delete_grid[i - 1][j]
            if pred is not None:
                deletion = earlier_start(
                    deletion, (pred[0] - gap_extend, pred[1], pred[2])
                )
            delete_grid[i][j] = deletion

            insertion: tuple[int, int, int] | None = None
            for grid, cost in (
                (match_grid, gap_open),
                (delete_grid, gap_open),
            ):
                pred = grid[i][j - 1]
                if pred is not None:
                    insertion = earlier_start(
                        insertion, (pred[0] - cost, pred[1], pred[2])
                    )
            pred = insert_grid[i][j - 1]
            if pred is not None:
                insertion = earlier_start(
                    insertion, (pred[0] - gap_extend, pred[1], pred[2])
                )
            insert_grid[i][j] = insertion

            # Only match/mismatch state cells are valid endpoints: a path
            # ending in a gap state is dominated by trimming its trailing
            # gap run (non-positive cost, smaller end coordinates).
            entry = match_grid[i][j]
            if entry is not None and entry[0] > 0:
                key = (entry[0], entry[1], i, entry[2], j)
                if best is None or (
                    -key[0], key[1], key[2], key[3], key[4]
                ) < (-best[0], best[1], best[2], best[3], best[4]):
                    best = key

    if best is None:
        return None
    return best[1], best[2], best[3], best[4]


def _expand_cigar(cigar: str) -> list[str]:
    """Expand a merged CIGAR string into one operation character per column."""
    ops: list[str] = []
    digits = ""
    for char in cigar:
        if char.isdigit():
            digits += char
        else:
            ops.extend([char] * int(digits))
            digits = ""
    return ops


def _build_result(
    reference_id: str,
    query_id: str,
    mode: str,
    ref: str,
    qry: str,
    score: int,
    cigar: str,
    reference_start: int,
    reference_end: int,
    query_start: int,
    query_end: int,
) -> PairwiseAlignment:
    aligned_reference: list[str] = []
    aligned_query: list[str] = []
    i, j = reference_start, query_start
    for op in _expand_cigar(cigar):
        if op in ("=", "X"):
            aligned_reference.append(ref[i])
            aligned_query.append(qry[j])
            i += 1
            j += 1
        elif op == "D":
            aligned_reference.append(ref[i])
            aligned_query.append("-")
            i += 1
        else:  # "I"
            aligned_reference.append("-")
            aligned_query.append(qry[j])
            j += 1
